//! Business engine of the control showcase.
//!
//! The engine depends only on the protocol; it never sees a window, a
//! control or a transport, and its tests run without any UI.

use bern::CommandError;
use bern::Value;
use bern::bind::BernValue;
use bern::media::MediaSource;
use bern::query::{Answer, Clock, SystemClock};
use bern::resources::Resources;
use showcase_protocol::showcase::{self, Action, Clip, Item, ItemKind, State};
use std::sync::Arc;

/// Resource name of a clip. The controlled test media are generated by
/// `examples/showcase/media/make-media.sh` and declared in `Bern.toml`.
fn clip_resource(clip: &Clip) -> &'static str {
    match clip {
        Clip::Pattern => "media/aurora.mp4",
        Clip::Bars => "media/tides.mp4",
        Clip::Damaged => "media/broken.mp4",
    }
}

pub struct ShowcaseEngine {
    state: State,
    next_id: i64,
    /// Time source of the asynchronous search; scenarios inject a manual clock.
    clock: Arc<dyn Clock>,
    /// Where the clips are: inside the app bundle, or the project's sources
    /// in tests.
    resources: Resources,
}

impl Default for ShowcaseEngine {
    fn default() -> Self {
        Self::new(SystemClock::new(), Resources::host())
    }
}

impl ShowcaseEngine {
    /// An engine whose search answers on `clock` and whose clips come from
    /// `resources`. The showcase cannot start without its clips: a missing
    /// one stops construction with the resource error.
    pub fn new(clock: impl Clock, resources: Resources) -> Self {
        let clip_source = |clip: Clip| {
            MediaSource::resource(&resources, clip_resource(&clip))
                .unwrap_or_else(|error| panic!("{}: {}", error.code, error.message))
        };
        let kinds = [
            (ItemKind::Documents, 12),
            (ItemKind::Photos, 248),
            (ItemKind::Music, 37),
            (ItemKind::Movies, 5),
            (ItemKind::Downloads, 19),
        ];
        let items = kinds
            .into_iter()
            .enumerate()
            .map(|(index, (kind, count))| Item {
                id: index as i64 + 1,
                kind,
                count,
                clip: clip_source(if index % 2 == 0 {
                    Clip::Pattern
                } else {
                    Clip::Bars
                }),
            })
            .collect::<Vec<_>>();
        let featured_source = clip_source(Clip::Pattern);
        Self {
            next_id: items.len() as i64 + 1,
            clock: Arc::new(clock),
            resources,
            state: State {
                last_action: None,
                activations: 0,
                volume: 50.0,
                items,
                featured: Clip::Pattern,
                featured_source,
                display_name: String::new(),
            },
        }
    }
}

impl showcase::Commands for ShowcaseEngine {
    fn record(&mut self, action: Action) -> Result<(), CommandError> {
        self.state.last_action = Some(action);
        self.state.activations = self.state.activations.saturating_add(1);
        Ok(())
    }

    fn set_volume(&mut self, value: f64) -> Result<(), CommandError> {
        if !(0.0..=100.0).contains(&value) {
            return Err(CommandError::new(
                "out_of_range",
                "volume must be between 0 and 100",
            ));
        }
        self.state.volume = value;
        Ok(())
    }

    fn add_item(&mut self, kind: ItemKind) -> Result<i64, CommandError> {
        let id = self.next_id;
        self.next_id += 1;
        let clip = self.clip_source(&Clip::Bars)?;
        self.state.items.push(Item {
            id,
            kind,
            count: 0,
            clip,
        });
        Ok(id)
    }

    fn remove_item(&mut self, id: i64) -> Result<(), CommandError> {
        let before = self.state.items.len();
        self.state.items.retain(|item| item.id != id);
        if self.state.items.len() == before {
            return Err(CommandError::new(
                "not_found",
                format!("no item with id {id}"),
            ));
        }
        Ok(())
    }

    fn feature(&mut self, clip: Clip) -> Result<(), CommandError> {
        self.state.featured_source = self.clip_source(&clip)?;
        self.state.featured = clip;
        Ok(())
    }

    fn set_display_name(&mut self, name: String) -> Result<(), CommandError> {
        Self::check_name(&name)?;
        self.state.display_name = name;
        Ok(())
    }
}

/// How long a search takes, in milliseconds. A broad search answers
/// later than a narrow one, so typing quickly produces answers out of
/// order: the first letter's search is still running when the second
/// letter's has already answered.
pub fn search_latency(text: &str) -> u64 {
    match text.chars().count() {
        0 => 250,
        1 => 900,
        2 => 450,
        _ => 150,
    }
}

/// Every name of an item's category: its translations and the variant name.
fn kind_names(kind: &ItemKind) -> Vec<String> {
    let Value::Enum { variant, .. } = kind.to_value() else {
        return Vec::new();
    };
    let Some(def) = showcase::descriptor().types.enum_def("ItemKind") else {
        return Vec::new();
    };
    let variant = &def.variants[variant as usize];
    let mut names = vec![variant.name.to_lowercase()];
    if let Some(label) = &variant.label {
        names.extend(label.translations.values().map(|text| text.to_lowercase()));
    }
    names
}

impl showcase::Queries for ShowcaseEngine {
    fn search_library(&self, text: String, answer: Answer<Vec<Item>>) {
        let needle = text.trim().to_lowercase();
        if needle.starts_with('!') {
            return answer.fail(CommandError::new(
                "invalid_search",
                "search text cannot start with `!`; search operators are not supported",
            ));
        }
        // The provider reads the state as of this request and answers later.
        let items = self.state.items.clone();
        self.clock.after_ms(
            search_latency(&needle),
            Box::new(move || {
                // Nobody waits for a superseded search: stop without
                // scanning. Dropping the answer reports the cancellation.
                if answer.is_cancelled() {
                    return;
                }
                let found = items
                    .into_iter()
                    .filter(|item| {
                        needle.is_empty()
                            || kind_names(&item.kind)
                                .iter()
                                .any(|name| name.contains(&needle))
                    })
                    .collect();
                answer.ok(found);
            }),
        );
    }
}

impl ShowcaseEngine {
    fn clip_source(&self, clip: &Clip) -> Result<MediaSource, CommandError> {
        MediaSource::resource(&self.resources, clip_resource(clip))
    }

    fn check_name(name: &str) -> Result<(), CommandError> {
        if name.trim().is_empty() || name.chars().count() > 40 {
            return Err(CommandError::new(
                "invalid_name",
                "a display name has 1 to 40 characters and is not only spaces",
            ));
        }
        Ok(())
    }
}

impl showcase::Engine for ShowcaseEngine {
    fn state(&self) -> &State {
        &self.state
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use bern::{CallContext, Entry, Host, Invocation};
    use std::path::Path;

    /// The resources `Bern.toml` declares, found in the project's sources:
    /// the same catalog the app bundle carries, so a clip the engine uses
    /// but the manifest does not declare fails here.
    fn declared_resources() -> Resources {
        let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("../Bern.toml");
        let config = bern_compiler::config::load(&manifest).expect("the showcase's Bern.toml");
        Resources::catalog(
            &config.dir,
            config.resources.into_iter().map(|resource| resource.name),
        )
    }

    fn engine() -> ShowcaseEngine {
        ShowcaseEngine::new(SystemClock::new(), declared_resources())
    }

    fn call(host: &Host, command: &str, params: Vec<Value>) -> Result<Value, CommandError> {
        let index = host.resolve(command).expect("registered command");
        host.dispatch_blocking(
            Invocation {
                command: index,
                params,
            },
            CallContext {
                entry: Entry::Test,
                request_id: "test".into(),
            },
        )
        .result
    }

    #[test]
    fn engine_runs_headless_through_the_shared_host() {
        let host = Host::start(showcase::Adapter(engine()));
        assert_eq!(host.descriptor().namespace, "showcase");
        call(&host, "showcase.record", vec![Action::Delete.to_value()]).unwrap();
        let (revision, state) = host.snapshot();
        assert_eq!(revision, 1);
        let last = host.descriptor().state_index("last_action").unwrap();
        assert_eq!(state[last], Some(Action::Delete).to_value());

        let id = call(&host, "showcase.add_item", vec![ItemKind::Music.to_value()]).unwrap();
        assert_eq!(id, Value::Int(6));
        call(&host, "showcase.remove_item", vec![Value::Int(6)]).unwrap();
        let error = call(&host, "showcase.remove_item", vec![Value::Int(6)]).unwrap_err();
        assert_eq!(error.code, "not_found");
    }

    #[test]
    fn invalid_values_are_rejected_by_the_engine_and_the_host() {
        let host = Host::start(showcase::Adapter(engine()));
        let error = call(&host, "showcase.set_volume", vec![Value::Float(140.0)]).unwrap_err();
        assert_eq!(error.code, "out_of_range");
        let error = call(
            &host,
            "showcase.set_volume",
            vec![Value::Text("loud".into())],
        )
        .unwrap_err();
        assert_eq!(error.code, "invalid_params");
        assert_eq!(host.snapshot().0, 0);
    }

    #[test]
    fn featured_clips_and_display_names() {
        let host = Host::start(showcase::Adapter(engine()));
        call(&host, "showcase.feature", vec![Clip::Damaged.to_value()]).unwrap();
        let (_, state) = host.snapshot();
        let source = host.descriptor().state_index("featured_source").unwrap();
        let featured = MediaSource::from_value(&state[source]).unwrap();
        let project = Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        assert_eq!(
            featured,
            MediaSource::file(project.join("media/broken.mp4"))
        );
        let error = call(
            &host,
            "showcase.set_display_name",
            vec![Value::Text("   ".into())],
        )
        .unwrap_err();
        assert_eq!(error.code, "invalid_name");
        call(
            &host,
            "showcase.set_display_name",
            vec![Value::Text("Ada".into())],
        )
        .unwrap();
    }

    #[test]
    fn clips_resolve_only_through_the_declared_resources() {
        // Every clip is declared and present, so only the damaged one fails
        // to play.
        let resources = declared_resources();
        for clip in [Clip::Pattern, Clip::Bars, Clip::Damaged] {
            assert!(resources.path(clip_resource(&clip)).is_ok());
        }
        // Without a host there are no resources, and no fallback to the
        // source tree: the engine cannot start.
        let started = std::panic::catch_unwind(ShowcaseEngine::default);
        let message = started.err().unwrap();
        let message = message.downcast_ref::<String>().unwrap();
        assert!(
            message.starts_with("resources_unavailable: cannot resolve `media/aurora.mp4`"),
            "{message}"
        );
    }

    #[test]
    fn descriptor_carries_labels_policies_and_external_names() {
        let descriptor = showcase::descriptor();
        descriptor.validate().unwrap();
        let (_, set_volume) = descriptor.command("showcase.set_volume").unwrap();
        assert_eq!(
            set_volume.policy.retry,
            bern::__private::protocol::Retry::Idempotent
        );
        assert_eq!(set_volume.errors, vec!["out_of_range"]);
        assert_eq!(set_volume.external.cli, vec!["showcase", "set-volume"]);
        assert_eq!(set_volume.external.mcp, "showcase_set_volume");
        let action = descriptor.types.enum_def("Action").unwrap();
        let label = action.variants[0].label.as_ref().unwrap();
        assert_eq!(label.get("en"), Some("Primary button"));
        assert_eq!(label.key, "Action.Primary");
    }

    /// The library page's search, driven the way the generated UI drives
    /// it: one subscription per window, a new parameter version per typed
    /// text, answers resolved by the session runtime, and a refresh when
    /// the items the query reads change. The clock decides when each
    /// search answers.
    mod search_scenario {
        use super::*;
        use bern::Subscription;
        use bern::query::{ManualClock, QuerySubscriptions, Resource, Ticket};
        use std::sync::Mutex;
        use std::time::Duration;

        type Subscriptions = Arc<Mutex<QuerySubscriptions>>;

        fn send(
            host: &Host,
            subscriptions: &Subscriptions,
            id: u64,
            query: usize,
            ticket: Ticket,
            params: Vec<Value>,
        ) {
            let answers = Arc::clone(subscriptions);
            host.dispatch_cancellable(
                Invocation {
                    command: query,
                    params,
                },
                CallContext {
                    entry: Entry::Ui,
                    request_id: format!("search-{}", ticket.version),
                },
                ticket.cancellation.clone(),
                move |outcome| {
                    answers.lock().unwrap().resolve(id, &ticket, outcome.result);
                },
            );
        }

        struct LibraryPage {
            host: Host,
            clock: ManualClock,
            subscriptions: Subscriptions,
            id: u64,
            query: usize,
            _updates: Subscription,
        }

        impl LibraryPage {
            fn open() -> Self {
                let clock = ManualClock::new();
                let host = Host::start(showcase::Adapter(ShowcaseEngine::new(
                    clock.clone(),
                    declared_resources(),
                )));
                let query = host.resolve("showcase.search_library").unwrap();
                let items = host.descriptor().state_index("items").unwrap();
                let subscriptions = Subscriptions::default();
                let id = subscriptions
                    .lock()
                    .unwrap()
                    .open("main#1", query, vec![items]);
                let engine = host.clone();
                let stale = Arc::clone(&subscriptions);
                let updates = host.subscribe(move |update| {
                    let changed: Vec<usize> =
                        update.changes.iter().map(|(field, _)| *field).collect();
                    let requests = stale.lock().unwrap().refresh(&changed);
                    for (id, ticket, params) in requests {
                        send(&engine, &stale, id, query, ticket, params);
                    }
                });
                Self {
                    host,
                    clock,
                    subscriptions,
                    id,
                    query,
                    _updates: updates,
                }
            }

            fn type_text(&self, text: &str) {
                let params = vec![Value::Text(text.into())];
                let ticket = self
                    .subscriptions
                    .lock()
                    .unwrap()
                    .request(self.id, params.clone())
                    .unwrap();
                send(
                    &self.host,
                    &self.subscriptions,
                    self.id,
                    self.query,
                    ticket,
                    params,
                );
            }

            /// Wait until `count` searches are running on the clock.
            fn running(&self, count: usize) {
                for _ in 0..2000 {
                    if self.clock.pending() >= count {
                        return;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                panic!("{count} searches should be running");
            }

            /// Item ids the page shows, by state.
            fn shown(&self) -> Resource<Vec<i64>> {
                let ids = |value: &Value| {
                    Vec::<Item>::from_value(value)
                        .unwrap()
                        .iter()
                        .map(|item| item.id)
                        .collect::<Vec<_>>()
                };
                match self
                    .subscriptions
                    .lock()
                    .unwrap()
                    .get(self.id)
                    .unwrap()
                    .state()
                {
                    Resource::Idle => Resource::Idle,
                    Resource::Loading => Resource::Loading,
                    Resource::Ready(value) => Resource::Ready(ids(value)),
                    Resource::Refreshing(value) => Resource::Refreshing(ids(value)),
                    Resource::Failed { error, previous } => Resource::Failed {
                        error: error.clone(),
                        previous: previous.as_ref().map(ids),
                    },
                }
            }

            fn discarded(&self) -> u64 {
                self.subscriptions
                    .lock()
                    .unwrap()
                    .get(self.id)
                    .unwrap()
                    .discarded()
            }
        }

        #[test]
        fn an_older_slow_search_never_overwrites_a_newer_one() {
            let page = LibraryPage::open();
            page.type_text("");
            assert_eq!(page.shown(), Resource::Loading);
            page.running(1);
            page.clock.advance(search_latency(""));
            assert_eq!(page.shown(), Resource::Ready(vec![1, 2, 3, 4, 5]));

            // "m" is broad and slow; "mo", typed while it runs, is fast.
            page.type_text("m");
            page.running(1);
            page.type_text("mo");
            page.running(2);
            assert_eq!(page.shown(), Resource::Refreshing(vec![1, 2, 3, 4, 5]));
            assert_eq!(search_latency("mo"), 450);
            page.clock.advance(450);
            assert_eq!(page.shown(), Resource::Ready(vec![4]));
            // The answer for "m" would arrive now. Its request was
            // cancelled, so the provider stopped and the page keeps "mo".
            assert_eq!(search_latency("m"), 900);
            page.clock.advance(450);
            assert_eq!(page.clock.pending(), 0);
            assert_eq!(page.shown(), Resource::Ready(vec![4]));
            assert_eq!(page.discarded(), 1);
        }

        #[test]
        fn search_matches_every_language_and_refreshes_when_items_change() {
            let page = LibraryPage::open();
            // Category labels match in Chinese as well as in English.
            page.type_text("影");
            page.running(1);
            page.clock.advance(search_latency("影"));
            assert_eq!(page.shown(), Resource::Ready(vec![4]));

            // The query reads `items`: adding one asks again with the same
            // text while the current rows stay visible.
            call(
                &page.host,
                "showcase.add_item",
                vec![ItemKind::Movies.to_value()],
            )
            .unwrap();
            page.running(1);
            assert_eq!(page.shown(), Resource::Refreshing(vec![4]));
            page.clock.advance(search_latency("影"));
            assert_eq!(page.shown(), Resource::Ready(vec![4, 6]));

            // A rejected search keeps the previous rows next to the error.
            page.type_text("!x");
            for _ in 0..2000 {
                if matches!(page.shown(), Resource::Failed { .. }) {
                    break;
                }
                std::thread::sleep(Duration::from_millis(1));
            }
            let Resource::Failed { error, previous } = page.shown() else {
                panic!("the search should fail");
            };
            assert_eq!(error.code, "invalid_search");
            assert_eq!(previous, Some(vec![4, 6]));

            // No match is a successful, empty answer.
            page.type_text("zzz");
            page.running(1);
            page.clock.advance(search_latency("zzz"));
            assert_eq!(page.shown(), Resource::Ready(vec![]));
        }

        #[test]
        fn external_entries_get_the_same_answers() {
            let clock = ManualClock::new();
            let host = Host::start(showcase::Adapter(ShowcaseEngine::new(
                clock.clone(),
                declared_resources(),
            )));
            let query = host.resolve("showcase.search_library").unwrap();
            assert!(host.is_query(query));
            let waiting = {
                let host = host.clone();
                std::thread::spawn(move || {
                    host.query_blocking(
                        Invocation {
                            command: query,
                            params: vec![Value::Text("Music".into())],
                        },
                        CallContext {
                            entry: Entry::Cli,
                            request_id: "cli".into(),
                        },
                        Duration::from_secs(5),
                    )
                })
            };
            while clock.pending() == 0 {
                std::thread::sleep(Duration::from_millis(1));
            }
            clock.advance(search_latency("music"));
            let outcome = waiting.join().unwrap();
            let items = Vec::<Item>::from_value(&outcome.result.unwrap()).unwrap();
            assert_eq!(
                items.iter().map(|item| item.id).collect::<Vec<_>>(),
                vec![3]
            );
        }
    }
}
